// STM32F401/F411 SDIO card-mode controller with a sparse, session-persistent SDHC card.
// Identification and single/multiple 512-byte block transfers use the real register/FIFO shape.
const BASE=0x40012c00,FIFO=BASE+0x80;
const S={CCRCFAIL:1,CTIMEOUT:4,TXUNDERR:16,RXOVERR:32,CMDREND:64,CMDSENT:128,DATAEND:256,STBITERR:512,DBCKEND:1024,TXFIFOHE:1<<14,RXFIFOHF:1<<15,TXFIFOF:1<<16,RXFIFOF:1<<17,TXFIFOE:1<<18,RXFIFOE:1<<19,TXDAVL:1<<20,RXDAVL:1<<21};
export class STMSDIO {
 constructor(r){this.r=r;this.present=r.board.cpu==='cortex-m4f'&&['PC8','PC9','PC10','PC11','PC12','PD2'].every(p=>r.board.gpio.includes(p));this.blocks=new Map();this.reset();}
 reset(){this.regs=new Map([[BASE,0],[BASE+4,0],[BASE+8,0],[BASE+12,0],[BASE+16,0],[BASE+20,0],[BASE+24,0],[BASE+28,0],[BASE+32,0],[BASE+36,0xffffffff],[BASE+40,0],[BASE+44,0],[BASE+48,0],[BASE+52,S.TXFIFOE|S.RXFIFOE],[BASE+60,0],[BASE+72,0]]);this.app=false;this.selected=false;this.rca=0x1234;this.fifo=[];this.data=null;this.pending=null;}
 clocked(){return this.present&&!!(this.r.regs.get(0x40023844)&(1<<11));}
 handles(a){return this.present&&a>=BASE&&a<=FIFO;}
 read(a,n=4){const x=a&~3;if(!this.handles(x))return undefined;if(n!==4||a!==x)throw Error('SDIO FIFO/register erişimi 32-bit hizalı olmalı.');if(x===FIFO){if(!this.data||this.data.write)throw Error('SDIO RX FIFO etkin değil.');const v=this.fifo.shift()??0;this.advanceRead();return v>>>0;}if(x===BASE+52)this.update();if(x===BASE+72)return this.fifo.length;return (this.regs.get(x)||0)>>>0;}
 write(a,v,n=4){const x=a&~3;if(!this.handles(x))return false;if(n!==4||a!==x)throw Error('SDIO FIFO/register yazımı 32-bit hizalı olmalı.');if(!this.clocked())return true;if(x===BASE+56){this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)&~v);return true;}if(x===FIFO){if(!this.data?.write)throw Error('SDIO TX FIFO etkin değil.');new DataView(this.data.bytes.buffer).setUint32(this.data.offset,v,true);this.data.offset+=4;this.completeIfDone();return true;}if(x===BASE+12){this.regs.set(x,v>>>0);if(v&1024)this.command(v&63);return true;}if(x===BASE+44){if(v&~0xfb)throw Error('SDIO ayrılmış/stream DCTRL seçimi.');this.regs.set(x,v>>>0);if(v&1)this.startData(v);return true;}if([BASE,BASE+4,BASE+8,BASE+36,BASE+40,BASE+60].includes(x)){this.regs.set(x,v>>>0);return true;}throw Error('SDIO register yazımı desteklenmiyor: 0x'+a.toString(16));}
 response(cmd,value=0){this.regs.set(BASE+16,cmd);this.regs.set(BASE+20,value>>>0);this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|(cmd===0?S.CMDSENT:S.CMDREND));}
 command(cmd){const arg=this.regs.get(BASE+8)||0;this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)&~(S.CTIMEOUT|S.CCRCFAIL|S.CMDREND|S.CMDSENT));if(!(this.regs.get(BASE)&3)){this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.CTIMEOUT);return;}if(cmd===0){this.selected=false;this.app=false;this.response(0);return;}if(cmd===8){this.response(cmd,arg&0xfff);return;}if(cmd===55){this.app=true;this.response(cmd,this.selected?0x900:0x120);return;}if(cmd===41&&this.app){this.app=false;this.response(cmd,0xc0ff8000);return;}if(cmd===2){this.regs.set(BASE+24,0x44556677);this.regs.set(BASE+28,0x8899aabb);this.regs.set(BASE+32,0xccddeeff);this.response(cmd,0x1aa2bb3c);return;}if(cmd===3){this.response(cmd,this.rca<<16);return;}if(cmd===7){this.selected=(arg>>>16)===this.rca;this.response(cmd,this.selected?0x900:0);return;}if(cmd===9){this.regs.set(BASE+24,0x5b590000);this.regs.set(BASE+28,0xedc97f80);this.regs.set(BASE+32,0x0a404000);this.response(cmd,0x400e0032);return;}if(cmd===13){this.response(cmd,this.selected?0x900:0x120);return;}if(cmd===16){if(arg!==512){this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.CCRCFAIL);return;}this.response(cmd);return;}if(cmd===12){this.finishData();this.response(cmd);return;}if([17,18,24,25].includes(cmd)){if(!this.selected){this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.CTIMEOUT);return;}this.pending={cmd,block:arg>>>0};this.response(cmd);return;}this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.CTIMEOUT);}
 startData(ctrl){const p=this.pending,length=this.regs.get(BASE+40)||0,write=!(ctrl&2);if(!p||write!==[24,25].includes(p.cmd)||length<1||length%512||length>65536){this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.STBITERR);return;}const bytes=new Uint8Array(length);if(!write)for(let off=0;off<length;off+=512)bytes.set(this.blocks.get(p.block+off/512)||new Uint8Array(512),off);this.data={write,block:p.block,bytes,offset:0};this.regs.set(BASE+48,length);this.refill();this.update();}
 refill(){if(!this.data||this.data.write)return;while(this.fifo.length<8&&this.data.offset+this.fifo.length*4<this.data.bytes.length){const i=this.data.offset+this.fifo.length*4;this.fifo.push(new DataView(this.data.bytes.buffer).getUint32(i,true));}}
 advanceRead(){this.data.offset+=4;this.regs.set(BASE+48,Math.max(0,this.data.bytes.length-this.data.offset));this.refill();this.completeIfDone();}
 completeIfDone(){const d=this.data;if(!d)return;this.regs.set(BASE+48,Math.max(0,d.bytes.length-d.offset));if(d.offset<d.bytes.length){this.update();return;}if(d.write)for(let off=0;off<d.bytes.length;off+=512)this.blocks.set(d.block+off/512,d.bytes.slice(off,off+512));this.data=null;this.pending=null;this.fifo=[];this.regs.set(BASE+52,(this.regs.get(BASE+52)||0)|S.DATAEND|S.DBCKEND);this.update();}
 finishData(){this.data=null;this.pending=null;this.fifo=[];this.regs.set(BASE+48,0);this.update();}
 update(){let s=this.regs.get(BASE+52)||0;s&=~(S.TXFIFOHE|S.RXFIFOHF|S.TXFIFOF|S.RXFIFOF|S.TXFIFOE|S.RXFIFOE|S.TXDAVL|S.RXDAVL);if(this.data?.write)s|=S.TXDAVL|S.TXFIFOHE;else if(this.data){s|=S.RXDAVL;if(this.fifo.length>=8)s|=S.RXFIFOHF;}else s|=S.TXFIFOE|S.RXFIFOE;this.regs.set(BASE+52,s);this.regs.set(BASE+72,this.fifo.length);}
 irq(){this.update();return this.clocked()&&!!((this.regs.get(BASE+52)||0)&(this.regs.get(BASE+60)||0));}
 card(){return {present:this.present,selected:this.selected,blocks:this.blocks.size,active:!!this.data};}
}
